const char *__asan_default_options() {
  return "verbosity=0:mallocator_may_return_null=1";
}

/* private data structures */
struct driver_data {
    const uint8_t *Data;
    size_t Size;
};

static struct sc_reader_operations fuzz_ops = {0};
static struct sc_reader_driver fuzz_drv = {
    "Fuzzing reader",
    "fuzz",
    &fuzz_ops,
    NULL
};

void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
{
    struct driver_data *data;
    uint16_t c_size;
    const uint8_t *c;

    if (chunk)
        *chunk = NULL;
    if (chunk_size)
        *chunk_size = 0;

    if (!chunk || !chunk_size || !reader) {
        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
        return;
    }
    data = reader->drv_data;
    if (!data || !data->Data || data->Size < sizeof c_size) {
        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
        return;
    }

    /* parse the length of the returned data on two bytes */
    c_size = *((uint16_t *) data->Data);
    /* consume two bytes from the fuzzing data */
    data->Size -= sizeof c_size;
    data->Data += sizeof c_size;

    if (data->Size < c_size) {
        c_size = data->Size;
    }

    /* consume the bytes from the fuzzing data */
    c = data->Data;
    data->Size -= c_size;
    data->Data += c_size;

    sc_debug_hex(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL,
        "Returning fuzzing chunk", c, c_size);

    *chunk = c;
    *chunk_size = c_size;
}

static int fuzz_reader_release(sc_reader_t *reader)
{
    if (reader) {
        free(reader->drv_data);
        reader->drv_data = NULL;
    }

    return SC_SUCCESS;
}

static int fuzz_reader_connect(sc_reader_t *reader)
{
    uint16_t chunk_size;
    const uint8_t *chunk;

    fuzz_get_chunk(reader, &chunk, &chunk_size);

    if (chunk_size > reader->atr.len)
        chunk_size = reader->atr.len;
    else
        reader->atr.len = chunk_size;

    if (chunk_size > 0)
        memcpy(reader->atr.value, chunk, chunk_size);

    return SC_SUCCESS;
}

static int fuzz_reader_disconnect(sc_reader_t *reader)
{
    return SC_SUCCESS;
}

static int fuzz_reader_transmit(sc_reader_t *reader, sc_apdu_t *apdu)
{
    const uint8_t *chunk;
    uint16_t chunk_size;

    fuzz_get_chunk(reader, &chunk, &chunk_size);

    if (chunk_size >= 2) {
        /* set the SW1 and SW2 status bytes (the last two bytes of
         * the response */
        apdu->sw1 = (unsigned int)chunk[chunk_size - 2];
        apdu->sw2 = (unsigned int)chunk[chunk_size - 1];
        chunk_size -= 2;
        /* set output length and copy the returned data if necessary */
        if (chunk_size <= apdu->resplen)
            apdu->resplen = chunk_size;

        if (apdu->resplen != 0)
            memcpy(apdu->resp, chunk, apdu->resplen);
    } else {
        apdu->sw1 = 0x6D;
        apdu->sw2 = 0x00;
        apdu->resplen = 0;
    }

    return SC_SUCCESS;
}

struct sc_reader_driver *sc_get_fuzz_driver(void)
{
    fuzz_ops.release = fuzz_reader_release;
    fuzz_ops.connect = fuzz_reader_connect;
    fuzz_ops.disconnect = fuzz_reader_disconnect;
    fuzz_ops.transmit = fuzz_reader_transmit;
    return &fuzz_drv;
}

void fuzz_add_reader(struct sc_context *ctx, const uint8_t *Data, size_t Size)
{
    sc_reader_t *reader;
    struct driver_data *data;
    char name[64] = {0};

    if (!(reader = calloc(1, sizeof(*reader)))
            || !(data = (calloc(1, sizeof(*data))))) {
        free(reader);
        return;
    }

    data->Data = Data;
    data->Size = Size;

    reader->driver = &fuzz_drv;
    reader->ops = &fuzz_ops;
    reader->drv_data = data;
    snprintf(name, sizeof name - 1, "%zu random byte%s reader (%p)",
            Size, Size == 1 ? "" : "s", Data);
    reader->name = strdup(name);

    reader->ctx = ctx;
    list_append(&ctx->readers, reader);
}

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    struct sc_context *ctx = NULL;
    struct sc_card *card = NULL;
    struct sc_pkcs15_card *p15card = NULL;
    struct sc_reader *reader;
    struct sc_pkcs15_object *obj;

    sc_establish_context(&ctx, "fuzz");
    if (!ctx)
        return 0;
    /* copied from sc_release_context() */
    while (list_size(&ctx->readers)) {
        sc_reader_t *rdr = (sc_reader_t *) list_get_at(&ctx->readers, 0);
        _sc_delete_reader(ctx, rdr);
    }
    if (ctx->reader_driver->ops->finish != NULL)
        ctx->reader_driver->ops->finish(ctx);

    ctx->reader_driver = sc_get_fuzz_driver();

    fuzz_add_reader(ctx, Data, Size);

    reader = sc_ctx_get_reader(ctx, 0);
    sc_connect_card(reader, &card);
    sc_pkcs15_bind(card, NULL, &p15card);

    if (p15card) {
        const uint8_t *in, *param;
        uint16_t in_len, param_len;
        fuzz_get_chunk(reader, &in, &in_len);
        fuzz_get_chunk(reader, &param, &param_len);
        for (obj = p15card->obj_list; obj != NULL; obj = obj->next) {
            u8 buf[0xFFFF];
            size_t i;

            int decipher_flags[] = {SC_ALGORITHM_RSA_RAW,
                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
                SC_ALGORITHM_RSA_PAD_ISO9796};
            for (i = 0; i < sizeof decipher_flags/sizeof *decipher_flags; i++) {
                sc_pkcs15_decipher(p15card, obj, decipher_flags[i],
                        in, in_len, buf, sizeof buf);
            }

            i = sizeof buf;
            sc_pkcs15_derive(p15card, obj, 0,
                    in, in_len, buf, &i);

            int wrap_flags[] = {0, SC_ALGORITHM_AES_ECB, SC_ALGORITHM_AES_CBC_PAD,
                SC_ALGORITHM_AES_CBC};
            for (i = 0; i < sizeof wrap_flags/sizeof *wrap_flags; i++) {
                struct sc_pkcs15_object target_key;
                sc_pkcs15_unwrap(p15card, obj, &target_key, wrap_flags[i],
                        in, in_len, param, param_len);
                unsigned long l = sizeof buf;
                sc_pkcs15_wrap(p15card, obj, &target_key, wrap_flags[i],
                        buf, &l, in, in_len);
            }

            int signature_flags[] = {SC_ALGORITHM_RSA_RAW,
                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
                SC_ALGORITHM_RSA_PAD_ISO9796,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA1,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA256,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA384,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA512,
                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA224,
                SC_ALGORITHM_ECDSA_RAW, SC_ALGORITHM_ECDSA_HASH_SHA1,
                SC_ALGORITHM_ECDSA_HASH_SHA224, SC_ALGORITHM_ECDSA_HASH_SHA256,
                SC_ALGORITHM_ECDSA_HASH_SHA384, SC_ALGORITHM_ECDSA_HASH_SHA512,
                SC_ALGORITHM_GOSTR3410_RAW, SC_ALGORITHM_GOSTR3410_HASH_GOSTR3411,
                SC_ALGORITHM_GOSTR3410_HASHES,
            };
            for (i = 0; i < sizeof signature_flags/sizeof *signature_flags; i++) {
                sc_pkcs15_compute_signature(p15card, obj, signature_flags[i],
                        in, in_len, buf, sizeof buf);
            }

            if (obj->type == SC_PKCS15_TYPE_AUTH_PIN) {
                sc_pkcs15_verify_pin(p15card, obj, in, in_len);
                sc_pkcs15_change_pin(p15card, obj, in, in_len, param, param_len);
                sc_pkcs15_unblock_pin(p15card, obj, in, in_len, param, param_len);
                sc_pkcs15_get_pin_info(p15card, obj);
            }
        }
        sc_pkcs15_card_free(p15card);
    }

    sc_disconnect_card(card);
    sc_release_context(ctx);

    return 0;
}

pgp_get_card_features(sc_card_t *card)
{
        struct pgp_priv_data *priv = DRVDATA(card);
        u8 *hist_bytes = card->reader->atr_info.hist_bytes;
        size_t hist_bytes_len = card->reader->atr_info.hist_bytes_len;
        size_t i;
        pgp_blob_t *blob, *blob6e, *blob73;

        /* parse card capabilities from historical bytes in ATR */
        if (hist_bytes_len > 0) {
                /* category indicator 0x00, 0x10 or 0x80 => compact TLV (ISO) */
                switch (hist_bytes[0]) {
                        case 0x00:
                                if (hist_bytes_len > 4) {
                                        pgp_parse_hist_bytes(card, hist_bytes+1, hist_bytes_len-4);
                                }
                                break;
                        case 0x80:
                                if (hist_bytes_len > 1) {
                                        pgp_parse_hist_bytes(card, hist_bytes+1, hist_bytes_len-1);
                                }
                                break;
                        case 0x10:
                                if (hist_bytes_len > 2) {
                                        pgp_parse_hist_bytes(card, hist_bytes+2, hist_bytes_len-2);
                                }
                                break;
                }
        }

        /* v1.1 does not support lifecycle via ACTIVATE & TERMINATE: set default */
        priv->ext_caps &= ~EXT_CAP_LCS;

        if (priv->bcd_version >= OPENPGP_CARD_2_0) {
                /* get card capabilities from "historical bytes" DO */
                if ((pgp_get_blob(card, priv->mf, 0x5f52, &blob) >= 0) &&
                    (blob->data != NULL) && (blob->data[0] == 0x00)) {

                        if (blob->len > 4) {
                                pgp_parse_hist_bytes(card, blob->data+1, blob->len-4);
                        }

                        /* get card status from historical bytes status indicator */
                        if ((blob->data[0] == 0x00) && (blob->len >= 4)) {
                                priv->state = blob->data[blob->len-3];
                                /* state not CARD_STATE_UNKNOWN => LCS supported */
                                if (priv->state != CARD_STATE_UNKNOWN)
                                        priv->ext_caps |= EXT_CAP_LCS;
                        }
                }
        }

        if (priv->bcd_version >= OPENPGP_CARD_3_1) {
                card->caps |= SC_CARD_CAP_ISO7816_PIN_INFO;
        }

        if ((pgp_get_blob(card, priv->mf, 0x006e, &blob6e) >= 0) &&
            (pgp_get_blob(card, blob6e, 0x0073, &blob73) >= 0)) {

                /* get "extended capabilities" DO */
                if ((pgp_get_blob(card, blob73, 0x00c0, &blob) >= 0) &&
                    (blob->data != NULL) && (blob->len > 0)) {
                        /* v2.0+: bit 0x04 in first byte means "algorithm attributes changeable" */
                        if ((blob->data[0] & 0x04) &&
                                        (priv->bcd_version >= OPENPGP_CARD_2_0))
                                priv->ext_caps |= EXT_CAP_ALG_ATTR_CHANGEABLE;
                        /* bit 0x08 in first byte means "support for private use DOs" */
                        if (blob->data[0] & 0x08)
                                priv->ext_caps |= EXT_CAP_PRIVATE_DO;
                        /* bit 0x10 in first byte means "support for CHV status byte changeable" */
                        if (blob->data[0] & 0x10)
                                priv->ext_caps |= EXT_CAP_C4_CHANGEABLE;
                        /* bit 0x20 in first byte means "support for Key Import" */
                        if (blob->data[0] & 0x20)
                                priv->ext_caps |= EXT_CAP_KEY_IMPORT;
                        /* bit 0x40 in first byte means "support for Get Challenge" */
                        if (blob->data[0] & 0x40) {
                                card->caps |= SC_CARD_CAP_RNG;
                                priv->ext_caps |= EXT_CAP_GET_CHALLENGE;
                        }
                        /* v2.0+: bit 0x80 in first byte means "support Secure Messaging" */
                        if ((blob->data[0] & 0x80) &&
                                        (priv->bcd_version >= OPENPGP_CARD_2_0))
                                priv->ext_caps |= EXT_CAP_SM;

                        if ((priv->bcd_version >= OPENPGP_CARD_2_0) && (blob->len >= 10)) {
                                /* v2.0+: max. challenge size is at bytes 3-4 */
                                priv->max_challenge_size = bebytes2ushort(blob->data + 2);
                                /* v2.0+: max. cert size it at bytes 5-6 */
                                priv->max_cert_size = bebytes2ushort(blob->data + 4);

                                if (priv->bcd_version < OPENPGP_CARD_3_0) {
                                        /* v2.x: SM algorithm is at byte 2: 0 == 3DES */
                                        priv->sm_algo = blob->data[1];
                                        if ((priv->sm_algo == SM_ALGO_NONE) && (priv->ext_caps & EXT_CAP_SM))
                                                priv->sm_algo = SM_ALGO_3DES;

                                        /* v2.x: max. send/receive sizes are at bytes 7-8 resp. 9-10 */
                                        card->max_send_size = bebytes2ushort(blob->data + 6);
                                        card->max_recv_size = bebytes2ushort(blob->data + 8);
                                }
                                else {
                                        /* v3.0+: SM algorithm is at byte 2: 0 == UNKNOWN */
                                        priv->sm_algo = blob->data[1];
                                        if ((priv->sm_algo == SM_ALGO_NONE) && (priv->ext_caps & EXT_CAP_SM))
                                                priv->sm_algo = SM_ALGO_UNKNOWN;
                                }
                                if (priv->bcd_version >= OPENPGP_CARD_3_3 && (blob->len >= 10)) {
                                        /* v3.3+: MSE for key numbers 2(DEC) and 3(AUT) supported */
                                        if (blob->data[9])
                                                priv->ext_caps |= EXT_CAP_MSE;
                                }
                        }
                }

                /* get max. PIN length from "CHV status bytes" DO */
                if ((pgp_get_blob(card, blob73, 0x00c4, &blob) >= 0) &&
                        (blob->data != NULL) && (blob->len > 1)) {
                        /* 2nd byte in "CHV status bytes" DO means "max. PIN length" */
                        card->max_pin_len = blob->data[1];
                }

                /* get _current_ algorithms & key lengths from "algorithm attributes" DOs
                 *
                 * All available algorithms should be already provided by pgp_init. However, if another
                 * algorithm is found in the "algorithm attributes" DOs, it is supported by the card as
                 * well and therefore added
                 * see OpenPGP card spec 1.1 & 2.x section 4.3.3.6 / v3.x section 4.4.3.7 */
                for (i = 0x00c1; i <= 0x00c3; i++) {
                        sc_cardctl_openpgp_keygen_info_t key_info;

                        /* OpenPGP card spec 1.1 & 2.x section 4.3.3.6 / v3.x section 4.4.3.7 */
                        if ((pgp_get_blob(card, blob73, i, &blob) >= 0) &&
                            (pgp_parse_algo_attr_blob(blob, &key_info) >= 0)) {

                                /* RSA [RFC 4880] */
                                if (key_info.algorithm == SC_OPENPGP_KEYALGO_RSA){
                                        /* OpenPGP card spec 1.1 & 2.x, section 7.2.9 & 7.2.10 /
                                         * v3.x section 7.2.11 & 7.2.12 */
                                        unsigned long flags = SC_ALGORITHM_RSA_PAD_PKCS1 |
                                                  SC_ALGORITHM_RSA_HASH_NONE |
                                                  SC_ALGORITHM_ONBOARD_KEY_GEN; /* key gen on card */
                                        _sc_card_add_rsa_alg(card, key_info.u.rsa.modulus_len, flags, 0);
                                }
                                /* v3.0+: ECC [RFC 4880 & 6637] */
                                else if (key_info.algorithm == SC_OPENPGP_KEYALGO_ECDH
                                        || key_info.algorithm == SC_OPENPGP_KEYALGO_ECDSA) {

                                        unsigned long flags, ext_flags;

                                        if (key_info.algorithm == SC_OPENPGP_KEYALGO_ECDH)
                                                flags = SC_ALGORITHM_ECDH_CDH_RAW;
                                        if (key_info.algorithm == SC_OPENPGP_KEYALGO_ECDSA)
                                                flags = SC_ALGORITHM_ECDSA_RAW;
                                        flags |= SC_ALGORITHM_ECDSA_HASH_NONE;
                                        flags |= SC_ALGORITHM_ONBOARD_KEY_GEN;
                                        ext_flags =  SC_ALGORITHM_EXT_EC_NAMEDCURVE;

                                        _sc_card_add_ec_alg(card, key_info.u.ec.key_length, flags, ext_flags,
                                                        &key_info.u.ec.oid);
                                }
                        }
                }

                if (priv->bcd_version >= OPENPGP_CARD_3_0) {
                        /* v3.0+: get length info from "extended length information" DO */
                        if ((pgp_get_blob(card, blob6e, 0x7f66, &blob) >= 0) &&
                                (blob->data != NULL) && (blob->len >= 8)) {
                                /* kludge: treat as SIMPLE DO and use appropriate offsets */
                                card->max_send_size = bebytes2ushort(blob->data + 2);
                                card->max_recv_size = bebytes2ushort(blob->data + 6);
                        }
                }
        }

        return SC_SUCCESS;
}


/**
 * ABI: terminate driver & free private data.
 */

pgp_parse_algo_attr_blob(const pgp_blob_t *blob, sc_cardctl_openpgp_keygen_info_t *key_info)
{
        struct sc_object_id oid;
        unsigned int j;

        if (blob == NULL || blob->data == NULL || blob->len == 0 ||
            blob->id < 0x00c1 || blob->id > 0x00c3 || key_info == NULL)
                return SC_ERROR_INCORRECT_PARAMETERS;

        key_info->key_id = blob->id - 0x00c0;   /* attribute algorithm blobs are C1 - C3 */

        switch (blob->data[0]) {
                case SC_OPENPGP_KEYALGO_RSA:
                        if (blob->len < 5)
                                return SC_ERROR_INCORRECT_PARAMETERS;

                        key_info->algorithm = SC_OPENPGP_KEYALGO_RSA;
                        key_info->u.rsa.modulus_len = bebytes2ushort(blob->data + 1);
                        key_info->u.rsa.exponent_len = bebytes2ushort(blob->data + 3);

                        key_info->u.rsa.keyformat = (blob->len > 5)
                                                  ? blob->data[5]
                                                  : SC_OPENPGP_KEYFORMAT_RSA_STD;
                        break;
                case SC_OPENPGP_KEYALGO_ECDH:
                case SC_OPENPGP_KEYALGO_ECDSA:

                        /* SC_OPENPGP_KEYALGO_ECDH || SC_OPENPGP_KEYALGO_ECDSA */
                        key_info->algorithm = blob->data[0];

                        sc_init_oid(&oid);
                        /* Create copy of oid from blob */
                        for (j=0; j < (blob->len-1); j++) {
                                oid.value[j] = blob->data[j+1]; /* ignore first byte of blob (algo ID) */
                        }

                        /* compare with list of supported ec_curves */
                        for (j=0; ec_curves[j].oid.value[0] >= 0; j++){
                                if (sc_compare_oid(&ec_curves[j].oid_binary, &oid)){
                                        key_info->u.ec.oid = ec_curves[j].oid;
                                        key_info->u.ec.key_length = ec_curves[j].size;
                                        break;
                                }
                        }
                        break;
                default:
                        return SC_ERROR_NOT_IMPLEMENTED;
        }

        return SC_SUCCESS;
}


